@aeval_monomial : ∀ {R : Type u_3} {S₁ : Type u_4} {σ : Type u_5} [inst : CommSemiring R] [inst_1 : CommSemiring S₁]
  [inst_2 : Algebra R S₁] (g : σ → S₁) (d : σ →₀ ℕ) (r : R),
  (aeval g) ((monomial d) r) = (algebraMap R S₁) r * d.prod fun i k ↦ g i ^ k

@Finsupp.weight : {σ : Type u_2} →
